import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdministrator";
import type { ITodoAppAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdministrator";

export async function test_api_admin_administrators_deleted_accounts_filtering(
  connection: api.IConnection,
) {
  // 1. Create multiple admin accounts with different roles and statuses
  const superAdminEmail = typia.random<string & tags.Format<"email">>();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const deletedSuperAdminEmail = typia.random<string & tags.Format<"email">>();
  const deletedAdminEmail = typia.random<string & tags.Format<"email">>();

  // Create active super admin
  const superAdmin = await api.functional.auth.admin.join(connection, {
    body: {
      email: superAdminEmail,
      password_hash: typia.random<string>(),
      first_name: "Super",
      last_name: "Admin",
      role_level: "super_admin",
      status: "active",
    } satisfies ITodoAppAdministrator.ICreate,
  });
  typia.assert(superAdmin);

  // Create active admin
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password_hash: typia.random<string>(),
      first_name: "Active",
      last_name: "Admin",
      role_level: "admin",
      status: "active",
    } satisfies ITodoAppAdministrator.ICreate,
  });
  typia.assert(admin);

  // Create active moderator
  const moderator = await api.functional.auth.admin.join(connection, {
    body: {
      email: moderatorEmail,
      password_hash: typia.random<string>(),
      first_name: "Active",
      last_name: "Moderator",
      role_level: "moderator",
      status: "active",
    } satisfies ITodoAppAdministrator.ICreate,
  });
  typia.assert(moderator);

  // Create soft-deleted super admin (for testing include_deleted functionality)
  const deletedSuperAdmin = await api.functional.auth.admin.join(connection, {
    body: {
      email: deletedSuperAdminEmail,
      password_hash: typia.random<string>(),
      first_name: "Deleted",
      last_name: "SuperAdmin",
      role_level: "super_admin",
      status: "deactivated",
    } satisfies ITodoAppAdministrator.ICreate,
  });
  typia.assert(deletedSuperAdmin);

  // Create soft-deleted admin
  const deletedAdmin = await api.functional.auth.admin.join(connection, {
    body: {
      email: deletedAdminEmail,
      password_hash: typia.random<string>(),
      first_name: "Deleted",
      last_name: "Admin",
      role_level: "admin",
      status: "deactivated",
    } satisfies ITodoAppAdministrator.ICreate,
  });
  typia.assert(deletedAdmin);

  // 2. Test 1: Search with default settings (include_deleted: false)
  // Should only return active accounts
  const searchWithoutDeleted =
    await api.functional.todoApp.admin.administrators.index(connection, {
      body: {
        page: 1,
        limit: 10,
        order_by: "created_at",
        order_direction: "asc",
      } satisfies ITodoAppAdministrator.IRequest,
    });
  typia.assert(searchWithoutDeleted);

  // Validate response structure
  TestValidator.equals(
    "pagination structure",
    searchWithoutDeleted.pagination.current,
    1,
  );
  TestValidator.equals("page limit", searchWithoutDeleted.pagination.limit, 10);
  TestValidator.predicate("has records", searchWithoutDeleted.data.length > 0);

  // Verify only active accounts are returned
  const activeAccountEmails = searchWithoutDeleted.data.map(
    (admin) => admin.email,
  );
  TestValidator.predicate(
    "contains active super admin",
    activeAccountEmails.includes(superAdminEmail),
  );
  TestValidator.predicate(
    "contains active admin",
    activeAccountEmails.includes(adminEmail),
  );
  TestValidator.predicate(
    "contains active moderator",
    activeAccountEmails.includes(moderatorEmail),
  );
  TestValidator.predicate(
    "excludes deleted super admin",
    !activeAccountEmails.includes(deletedSuperAdminEmail),
  );
  TestValidator.predicate(
    "excludes deleted admin",
    !activeAccountEmails.includes(deletedAdminEmail),
  );

  // 3. Test 2: Search with include_deleted: true
  // Should include both active and soft-deleted accounts
  const searchWithDeleted =
    await api.functional.todoApp.admin.administrators.index(connection, {
      body: {
        page: 1,
        limit: 10,
        include_deleted: true,
        order_by: "created_at",
        order_direction: "asc",
      } satisfies ITodoAppAdministrator.IRequest,
    });
  typia.assert(searchWithDeleted);

  // Verify both active and deleted accounts are included
  const allAccountEmails = searchWithDeleted.data.map((admin) => admin.email);
  TestValidator.predicate(
    "contains active super admin",
    allAccountEmails.includes(superAdminEmail),
  );
  TestValidator.predicate(
    "contains active admin",
    allAccountEmails.includes(adminEmail),
  );
  TestValidator.predicate(
    "contains active moderator",
    allAccountEmails.includes(moderatorEmail),
  );
  TestValidator.predicate(
    "includes deleted super admin",
    allAccountEmails.includes(deletedSuperAdminEmail),
  );
  TestValidator.predicate(
    "includes deleted admin",
    allAccountEmails.includes(deletedAdminEmail),
  );

  // Verify total count is higher when including deleted
  TestValidator.predicate(
    "more records with deleted included",
    searchWithDeleted.data.length >= searchWithoutDeleted.data.length,
  );

  // 4. Test 3: Role-level filtering with include_deleted
  // Test filtering for super_admin role including deleted accounts
  const superAdminSearch =
    await api.functional.todoApp.admin.administrators.index(connection, {
      body: {
        page: 1,
        limit: 10,
        role_level: "super_admin",
        include_deleted: true,
      } satisfies ITodoAppAdministrator.IRequest,
    });
  typia.assert(superAdminSearch);

  // Should find both active and deleted super admins
  const superAdminResults = superAdminSearch.data.filter(
    (admin) => admin.role_level === "super_admin",
  );
  TestValidator.predicate(
    "finds active super admin",
    superAdminResults.some((admin) => admin.email === superAdminEmail),
  );
  TestValidator.predicate(
    "finds deleted super admin",
    superAdminResults.some((admin) => admin.email === deletedSuperAdminEmail),
  );

  // 5. Test 4: Status filtering with include_deleted
  // Test filtering for deactivated status
  const deactivatedSearch =
    await api.functional.todoApp.admin.administrators.index(connection, {
      body: {
        page: 1,
        limit: 10,
        status: "deactivated",
        include_deleted: true,
      } satisfies ITodoAppAdministrator.IRequest,
    });
  typia.assert(deactivatedSearch);

  // Should only return deactivated accounts
  const deactivatedResults = deactivatedSearch.data;
  TestValidator.predicate(
    "only returns deactivated accounts",
    deactivatedResults.every(
      (admin) =>
        admin.email === deletedSuperAdminEmail ||
        admin.email === deletedAdminEmail,
    ),
  );
  TestValidator.predicate(
    "includes both deleted accounts",
    deactivatedResults.length >= 2,
  );

  // 6. Test 5: Email-specific search with deleted accounts
  const emailSearch = await api.functional.todoApp.admin.administrators.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        email: deletedAdminEmail,
        include_deleted: true,
      } satisfies ITodoAppAdministrator.IRequest,
    },
  );
  typia.assert(emailSearch);

  // Should find the specific deleted admin by email
  TestValidator.equals(
    "finds deleted admin by email",
    emailSearch.data.length,
    1,
  );
  TestValidator.equals(
    "email matches",
    emailSearch.data[0].email,
    deletedAdminEmail,
  );

  // 7. Test 6: Search without include_deleted for specific email
  // Should not find deleted account when include_deleted is false
  const emailSearchWithoutDeleted =
    await api.functional.todoApp.admin.administrators.index(connection, {
      body: {
        page: 1,
        limit: 10,
        email: deletedAdminEmail,
        include_deleted: false,
      } satisfies ITodoAppAdministrator.IRequest,
    });
  typia.assert(emailSearchWithoutDeleted);

  // Should not find the deleted admin
  TestValidator.equals(
    "does not find deleted admin without flag",
    emailSearchWithoutDeleted.data.length,
    0,
  );

  // 8. Test 7: Pagination with deleted accounts
  const paginationSearch =
    await api.functional.todoApp.admin.administrators.index(connection, {
      body: {
        page: 1,
        limit: 2,
        include_deleted: true,
        order_by: "created_at",
        order_direction: "asc",
      } satisfies ITodoAppAdministrator.IRequest,
    });
  typia.assert(paginationSearch);

  // Validate pagination metadata
  TestValidator.equals(
    "pagination page",
    paginationSearch.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit",
    paginationSearch.pagination.limit,
    2,
  );
  TestValidator.predicate(
    "pagination has records",
    paginationSearch.data.length > 0,
  );
  TestValidator.predicate(
    "total records > page size",
    paginationSearch.pagination.records > paginationSearch.data.length,
  );

  // 9. Test 8: Full-text search across mixed account states
  const fullTextSearch =
    await api.functional.todoApp.admin.administrators.index(connection, {
      body: {
        page: 1,
        limit: 10,
        search: "Admin",
        include_deleted: true,
      } satisfies ITodoAppAdministrator.IRequest,
    });
  typia.assert(fullTextSearch);

  // Should find accounts containing "Admin" in names (both active and deleted)
  const adminSearchResults = fullTextSearch.data;
  TestValidator.predicate(
    "finds accounts with 'Admin' in name",
    adminSearchResults.length > 0,
  );

  // Verify we have both active and deleted accounts in results
  const foundEmails = adminSearchResults.map((admin) => admin.email);
  TestValidator.predicate(
    "includes active admin",
    foundEmails.includes(adminEmail),
  );
  TestValidator.predicate(
    "includes deleted admin",
    foundEmails.includes(deletedAdminEmail),
  );

  console.log(
    "All administrator deleted account filtering tests passed successfully!",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdministrator";
import type { ITodoAppSystemMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemMetadata";

export async function test_api_system_metadata_deletion_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for authentication
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "AdminPassword123!";

  const adminAuth: ITodoAppAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password_hash: adminPassword,
        first_name: RandomGenerator.name(1),
        last_name: RandomGenerator.name(1),
        role_level: "admin",
        status: "active",
      } satisfies ITodoAppAdministrator.ICreate,
    });
  typia.assert(adminAuth);

  // Step 2: Create system administrator account
  const systemAdmin: ITodoAppAdministrator =
    await api.functional.todoApp.administrators.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password_hash: "SystemAdmin123!",
        first_name: RandomGenerator.name(1),
        last_name: RandomGenerator.name(1),
        role_level: "super_admin",
        status: "active",
      } satisfies ITodoAppAdministrator.ICreate,
    });
  typia.assert(systemAdmin);

  // Step 3: Test deletion of a known system configuration
  // Using a common system config key that should exist for testing
  const configKey: string = "system.theme.default";

  // Step 4: Perform soft deletion of the system metadata
  const deletedMetadata: ITodoAppSystemMetadata =
    await api.functional.todoApp.admin.system.metadata.erase(connection, {
      configKey: configKey,
    });
  typia.assert(deletedMetadata);

  // Step 5: Validate soft deletion - configuration should be marked as deleted
  TestValidator.predicate(
    "deleted_at timestamp should be set after deletion",
    deletedMetadata.deleted_at !== null &&
      deletedMetadata.deleted_at !== undefined,
  );

  TestValidator.predicate(
    "deleted_at should be a valid date-time string",
    typeof deletedMetadata.deleted_at === "string" &&
      !isNaN(Date.parse(deletedMetadata.deleted_at!)),
  );

  // Step 6: Validate that the metadata record still exists but is marked as deleted
  TestValidator.equals(
    "config_key should match the requested deletion key",
    deletedMetadata.config_key,
    configKey,
  );

  // Step 7: Validate audit trail preservation - record should still be retrievable
  TestValidator.predicate(
    "metadata ID should be preserved for audit purposes",
    deletedMetadata.id !== null && deletedMetadata.id !== undefined,
  );

  TestValidator.predicate(
    "created_at timestamp should be preserved",
    deletedMetadata.created_at !== null &&
      deletedMetadata.created_at !== undefined,
  );

  // Step 8: Validate metadata properties are still accessible after soft deletion
  TestValidator.predicate(
    "config_value should remain accessible",
    deletedMetadata.config_value !== null &&
      deletedMetadata.config_value !== undefined,
  );

  TestValidator.predicate(
    "config_type should be preserved",
    deletedMetadata.config_type !== null &&
      deletedMetadata.config_type !== undefined,
  );

  TestValidator.predicate(
    "category should be preserved",
    deletedMetadata.category !== null && deletedMetadata.category !== undefined,
  );

  // Step 9: Validate deletion timestamp is recent and valid
  const deletionTime = new Date(deletedMetadata.deleted_at!);
  const now = new Date();
  const timeDiff = now.getTime() - deletionTime.getTime();

  TestValidator.predicate(
    "deletion should have occurred recently (within test execution time)",
    timeDiff >= 0 && timeDiff <= 60000, // Within last minute
  );

  // Step 10: Validate that updated_at reflects the deletion time
  TestValidator.predicate(
    "updated_at should be set and reflect recent modification",
    deletedMetadata.updated_at !== null &&
      deletedMetadata.updated_at !== undefined &&
      new Date(deletedMetadata.updated_at).getTime() >= deletionTime.getTime(),
  );

  // Step 11: Validate that administrative metadata is preserved
  TestValidator.predicate(
    "administrator tracking should be preserved",
    deletedMetadata.created_by_administrator_id !== null &&
      deletedMetadata.created_by_administrator_id !== undefined,
  );

  // Step 12: Verify soft deletion maintains referential integrity
  TestValidator.predicate(
    "environment scope should remain intact",
    deletedMetadata.environment_scope !== null &&
      deletedMetadata.environment_scope !== undefined,
  );

  TestValidator.predicate(
    "system configuration flag should be preserved",
    typeof deletedMetadata.is_system_config === "boolean",
  );

  TestValidator.predicate(
    "active status should be preserved",
    typeof deletedMetadata.is_active === "boolean",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdministrator";
import type { ITodoAppSystemMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemMetadata";

/**
 * Test deletion behavior when attempting to remove non-existent system metadata
 * configuration.
 *
 * This test validates proper error handling for configuration entries that
 * don't exist, ensuring system stability and appropriate error responses when
 * administrators attempt to delete non-existent metadata configurations.
 *
 * The test follows a systematic approach:
 *
 * 1. Create admin account through authentication system
 * 2. Establish administrator context for privileged operations
 * 3. Attempt to delete a non-existent configuration key
 * 4. Validate error handling and system stability
 *
 * This ensures the TodoApp system handles invalid deletion requests gracefully
 * while maintaining system integrity and providing clear feedback to
 * administrators.
 */
export async function test_api_system_metadata_deletion_nonexistent_config(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for testing
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = "SecurePassword123!";

  const adminAccount: ITodoAppAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password_hash: adminPassword,
        first_name: "Test",
        last_name: "Admin",
        role_level: "admin",
        status: "active",
      } satisfies ITodoAppAdministrator.ICreate,
    });
  typia.assert(adminAccount);

  // Step 2: Establish administrator context
  const administrator: ITodoAppAdministrator =
    await api.functional.todoApp.administrators.create(connection, {
      body: {
        email: adminEmail,
        password_hash: adminPassword,
        first_name: "Test",
        last_name: "Admin",
        role_level: "admin",
        status: "active",
      } satisfies ITodoAppAdministrator.ICreate,
    });
  typia.assert(administrator);

  // Step 3: Attempt to delete non-existent configuration
  const nonExistentConfigKey: string = `non_existent_config_${RandomGenerator.alphaNumeric(8)}`;

  await TestValidator.error(
    "deleting non-existent configuration should fail",
    async () => {
      await api.functional.todoApp.admin.system.metadata.erase(connection, {
        configKey: nonExistentConfigKey,
      });
    },
  );

  // Step 4: Verify system stability by attempting to read the configuration
  // This should also fail, confirming the configuration doesn't exist
  await TestValidator.error(
    "non-existent configuration should not be readable",
    async () => {
      // Note: We're testing error handling, so we attempt another operation
      // to ensure the system remains stable after the failed deletion
      await api.functional.todoApp.admin.system.metadata.erase(connection, {
        configKey: `another_non_existent_key_${RandomGenerator.alphaNumeric(6)}`,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppSystemMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppSystemMetadata";
import type { ITodoAppAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdministrator";
import type { ITodoAppSystemMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppSystemMetadata";

/**
 * Test system metadata retrieval by admin user.
 *
 * This test validates that system administrators can successfully retrieve
 * complete system configuration and operational metadata from the centralized
 * configuration management system. The test follows a comprehensive workflow:
 *
 * 1. Admin Account Creation: Creates a new administrator account to establish
 *    authentication context for privileged system access
 * 2. Metadata Retrieval: Retrieves all system configuration entries using the
 *    admin metadata endpoint
 * 3. Response Structure Validation: Validates pagination and data array structure
 * 4. Configuration Content Verification: Verifies comprehensive configuration
 *    coverage across different types (boolean flags, numeric values, string
 *    configs, JSON objects)
 * 5. Administrative Access Validation: Confirms proper admin-level metadata access
 *
 * The test ensures that the metadata system provides complete visibility into
 * all system configurations including feature flags, system limits, UI
 * settings, security settings, performance settings, integration settings, and
 * operational settings with proper validation schemas, default values, and
 * range restrictions.
 */
export async function test_api_system_metadata_retrieval_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for authentication
  const adminAccount = {
    email: typia.random<string & tags.Format<"email">>(),
    password_hash: RandomGenerator.alphabets(16),
    first_name: RandomGenerator.name(1),
    last_name: RandomGenerator.name(1),
    role_level: "admin",
    status: "active",
  } satisfies ITodoAppAdministrator.ICreate;

  const admin: ITodoAppAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminAccount,
    });
  typia.assert(admin);

  // Step 2: Retrieve system metadata using admin access
  const metadataResponse: IPageITodoAppSystemMetadata.ISummary =
    await api.functional.todoApp.admin.system.metadata.get(connection);
  typia.assert(metadataResponse);

  // Step 3: Validate response structure and pagination
  TestValidator.equals(
    "response contains pagination data",
    metadataResponse.pagination.current !== undefined &&
      metadataResponse.pagination.limit !== undefined &&
      metadataResponse.pagination.records !== undefined &&
      metadataResponse.pagination.pages !== undefined,
    true,
  );

  // Step 4: Validate data array exists
  TestValidator.equals(
    "response contains data array",
    Array.isArray(metadataResponse.data),
    true,
  );

  // Step 5: Validate metadata entries if any exist
  if (metadataResponse.data.length > 0) {
    // Validate first entry structure
    const firstMetadata: ITodoAppSystemMetadata.ISummary =
      metadataResponse.data[0];
    TestValidator.equals(
      "first metadata entry has required fields",
      firstMetadata.id !== undefined &&
        firstMetadata.config_key !== undefined &&
        firstMetadata.config_value !== undefined &&
        firstMetadata.config_type !== undefined &&
        firstMetadata.category !== undefined &&
        firstMetadata.description !== undefined,
      true,
    );

    // Validate configuration types are valid
    const validConfigTypes = ["string", "number", "boolean", "json", "url"];
    TestValidator.predicate(
      "config types are valid",
      validConfigTypes.includes(firstMetadata.config_type),
    );

    // Validate categories are valid
    const validCategories = [
      "feature_flags",
      "system_limits",
      "ui_settings",
      "security_settings",
      "performance_settings",
      "integration_settings",
      "operational_settings",
    ];
    TestValidator.predicate(
      "config categories are valid",
      validCategories.includes(firstMetadata.category),
    );

    // Test validation that metadata covers various types
    let hasBooleanConfig = false;
    let hasNumericConfig = false;
    let hasStringConfig = false;
    let hasJsonConfig = false;

    for (const entry of metadataResponse.data) {
      if (entry.config_type === "boolean" && !hasBooleanConfig)
        hasBooleanConfig = true;
      if (entry.config_type === "number" && !hasNumericConfig)
        hasNumericConfig = true;
      if (entry.config_type === "string" && !hasStringConfig)
        hasStringConfig = true;
      if (entry.config_type === "json" && !hasJsonConfig) hasJsonConfig = true;
    }

    // Check that the metadata response contains diverse configuration types
    TestValidator.predicate(
      "metadata contains diverse configuration types",
      metadataResponse.data.some((entry) => entry.config_type === "string") &&
        metadataResponse.data.some((entry) => entry.config_type === "number") &&
        metadataResponse.data.some(
          (entry) => entry.config_type === "boolean",
        ) &&
        metadataResponse.data.some((entry) => entry.config_type === "json"),
    );

    // Validate that system metadata includes proper timestamps
    TestValidator.equals(
      "metadata entries have proper timestamps",
      firstMetadata.created_at !== undefined &&
        firstMetadata.updated_at !== undefined,
      true,
    );

    // Test environment scope validation
    const validEnvScopes = ["all", "development", "staging", "production"];
    TestValidator.predicate(
      "environment scopes are valid",
      validEnvScopes.includes(firstMetadata.environment_scope),
    );
  } else {
    // If no metadata exists, validate the empty response structure
    TestValidator.equals(
      "empty metadata response is valid",
      metadataResponse.data.length === 0,
      true,
    );
  }

  // Step 6: Validate admin authentication context
  TestValidator.equals(
    "admin authentication succeeded",
    admin.id !== undefined && admin.token !== undefined,
    true,
  );

  TestValidator.equals(
    "JWT tokens are properly issued",
    admin.token.access !== undefined &&
      admin.token.refresh !== undefined &&
      admin.token.expired_at !== undefined,
    true,
  );

  // Step 7: Final validation that system metadata endpoint is accessible to admin
  TestValidator.equals(
    "admin can access system metadata endpoint",
    metadataResponse !== null && metadataResponse !== undefined,
    true,
  );
}

