import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAuditLog";
import { IPageITodoAppAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAuditLog";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoAppAdminAdministratorsAdministratorIdAuditLogs(props: {
  admin: AdminPayload;
  administratorId: string & tags.Format<"uuid">;
  body: ITodoAppAuditLog.IRequest;
}): Promise<IPageITodoAppAuditLog> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;

  const buildWhereCondition = () => {
    const conditions: Record<string, unknown> & {
      created_at?: { gte?: string; lte?: string };
    } = {
      actor_administrator_id: props.administratorId,
    };

    // Filter by specific action type
    if (props.body.action_type) {
      conditions.action_type = props.body.action_type;
    }

    // Filter by specific entity type
    if (props.body.entity_type) {
      conditions.entity_type = props.body.entity_type;
    }

    // Filter by severity level
    if (props.body.severity_level) {
      conditions.severity_level = props.body.severity_level;
    }

    // Filter by specific member actor
    if (props.body.actor_member_id) {
      conditions.actor_member_id = props.body.actor_member_id;
    }

    // Filter by specific member target
    if (props.body.target_member_id) {
      conditions.target_member_id = props.body.target_member_id;
    }

    // Filter by specific todo target
    if (props.body.target_todo_id) {
      conditions.target_todo_id = props.body.target_todo_id;
    }

    // Handle soft delete filtering
    if (!props.body.include_deleted) {
      conditions.deleted_at = null;
    }

    // Date range filtering
    if (props.body.created_after || props.body.created_before) {
      conditions.created_at = {} as { gte?: string; lte?: string };
      if (props.body.created_after) {
        conditions.created_at.gte = props.body.created_after;
      }
      if (props.body.created_before) {
        conditions.created_at.lte = props.body.created_before;
      }
    }

    // Full-text search using GIN indexes
    if (props.body.search) {
      conditions.OR = [
        { action_description: { contains: props.body.search } },
        { user_agent: { contains: props.body.search } },
      ];
    }

    return conditions;
  };

  const whereCondition = buildWhereCondition();

  // Build order by clause with validation
  const validOrderFields = [
    "created_at",
    "updated_at",
    "action_type",
    "severity_level",
  ];
  const orderByField = validOrderFields.includes(props.body.order_by || "")
    ? props.body.order_by
    : "created_at";
  const orderDirection = props.body.order_direction === "asc" ? "asc" : "desc";

  const orderBy = {
    [orderByField!]: orderDirection,
  };

  const [auditLogs, total] = await Promise.all([
    MyGlobal.prisma.todo_app_audit_logs.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.todo_app_audit_logs.count({
      where: whereCondition,
    }),
  ]);

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: auditLogs.map((auditLog) => ({
      id: auditLog.id,
      actor_member_id: auditLog.actor_member_id ?? undefined,
      actor_administrator_id: auditLog.actor_administrator_id ?? undefined,
      target_member_id: auditLog.target_member_id ?? undefined,
      target_todo_id: auditLog.target_todo_id ?? undefined,
      action_type: auditLog.action_type,
      action_description: auditLog.action_description,
      entity_type: auditLog.entity_type,
      entity_id: auditLog.entity_id ?? undefined,
      old_values: auditLog.old_values ?? undefined,
      new_values: auditLog.new_values ?? undefined,
      ip_address: auditLog.ip_address ?? undefined,
      user_agent: auditLog.user_agent ?? undefined,
      session_id: auditLog.session_id ?? undefined,
      request_id: auditLog.request_id ?? undefined,
      severity_level: auditLog.severity_level,
      created_at: toISOStringSafe(auditLog.created_at),
      updated_at: auditLog.updated_at
        ? toISOStringSafe(auditLog.updated_at)
        : undefined,
      deleted_at: auditLog.deleted_at
        ? toISOStringSafe(auditLog.deleted_at)
        : undefined,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoAppAdminAdministratorsAdministratorIdTodos(props: {
  admin: AdminPayload;
  body: ITodoAppTodo.IRequest;
}): Promise<IPageITodoAppTodo.ISummary> {
  const { admin, body } = props;

  // Verify admin has permission to access todos (security validation)
  if (admin.type !== "admin") {
    throw new HttpException(
      "Unauthorized access to admin todo operations",
      403,
    );
  }

  // Build dynamic where conditions based on request filters
  const whereConditions: Record<string, unknown> = {
    // Ensure todos belong to the specified administrator
    todo_app_administrator_id: admin.id,
  };

  // Add text search across title and description
  if (body.search) {
    whereConditions.OR = [
      { title: { contains: body.search, mode: "insensitive" } },
      { description: { contains: body.search, mode: "insensitive" } },
    ];
  }

  // Filter by status values
  if (body.status && body.status.length > 0) {
    whereConditions.status = { in: body.status };
  }

  // Filter by priority levels
  if (body.priority && body.priority.length > 0) {
    whereConditions.priority = { in: body.priority };
  }

  // Filter by category
  if (body.category) {
    whereConditions.category = { equals: body.category };
  }

  // Filter by business workflow status
  if (body.business_status && body.business_status.length > 0) {
    whereConditions.business_status = { in: body.business_status };
  }

  // Handle completed todo inclusion
  if (body.include_completed === false) {
    whereConditions.status = { not: "completed" };
  }

  // Filter by creation date range
  if (body.date_from || body.date_to) {
    (whereConditions as any).created_at = {} as Prisma.DateTimeFilter;
    if (body.date_from)
      (whereConditions as any).created_at.gte = new Date(body.date_from);
    if (body.date_to)
      (whereConditions as any).created_at.lte = new Date(body.date_to);
  }

  // Filter by due date range
  if (body.due_date_from || body.due_date_to) {
    (whereConditions as any).due_date = {} as Prisma.DateTimeFilter;
    if (body.due_date_from)
      (whereConditions as any).due_date.gte = new Date(body.due_date_from);
    if (body.due_date_to)
      (whereConditions as any).due_date.lte = new Date(body.due_date_to);
  }

  // Setup pagination parameters with validation
  const page = Math.max(1, body.page ?? 1);
  const limit = Math.min(Math.max(1, body.limit ?? 20), 100); // Cap at 100 per page
  const skip = (page - 1) * limit;

  // Build sort order configuration
  let orderBy: Record<string, unknown> = {};
  switch (body.sort_by) {
    case "updated_at":
      orderBy = { updated_at: body.sort_order ?? "desc" };
      break;
    case "due_date":
      orderBy = { due_date: body.sort_order ?? "asc" };
      break;
    case "priority":
      // Standard priority ordering: urgent > high > medium > low
      orderBy = { priority: body.sort_order === "asc" ? "asc" : "desc" };
      break;
    case "title":
      orderBy = { title: body.sort_order ?? "asc" };
      break;
    case "status":
      orderBy = { status: body.sort_order ?? "asc" };
      break;
    default: // created_at
      orderBy = { created_at: body.sort_order ?? "desc" };
      break;
  }

  try {
    // Execute database operations with proper error handling
    const [todos, totalCount] = await Promise.all([
      MyGlobal.prisma.todo_app_todos.findMany({
        where: whereConditions,
        skip,
        take: limit,
        orderBy,
      }),
      MyGlobal.prisma.todo_app_todos.count({ where: whereConditions }),
    ]);

    // Transform database results to API format with proper datetime conversion
    const todoSummaries = todos.map((todo) => ({
      id: todo.id as string & tags.Format<"uuid">,
      title: todo.title,
      description: todo.description ?? undefined,
      status: todo.status as
        | "pending"
        | "in_progress"
        | "completed"
        | "cancelled",
      business_status: todo.business_status as
        | "active"
        | "on_hold"
        | "archived",
      priority: todo.priority as "low" | "medium" | "high" | "urgent",
      category: todo.category ?? undefined,
      due_date: todo.due_date ? toISOStringSafe(todo.due_date) : undefined,
      created_at: toISOStringSafe(todo.created_at),
      updated_at: toISOStringSafe(todo.updated_at),
      completed_at: todo.completed_at
        ? toISOStringSafe(todo.completed_at)
        : undefined,
    }));

    // Return paginated results with complete metadata
    return {
      data: todoSummaries,
      pagination: {
        current: page,
        limit,
        records: totalCount,
        pages: Math.ceil(totalCount / limit),
      },
    };
  } catch (error) {
    // Handle database operation errors gracefully
    throw new HttpException(
      "Failed to retrieve todos: " +
        (error instanceof Error ? error.message : "Unknown error"),
      500,
    );
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchTodoAppAdminTodos(props: {
  admin: AdminPayload;
  body: ITodoAppTodo.IRequest;
}): Promise<IPageITodoAppTodo.ISummary> {
  const { admin, body } = props;

  // Pagination parameters
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // Build dynamic where conditions
  const whereConditions: Record<string, unknown> = {
    // Exclude soft-deleted todos
    deleted_at: null,

    // Status filtering
    ...(body.status &&
      body.status.length > 0 && {
        status: { in: body.status },
      }),

    // Business status filtering
    ...(body.business_status &&
      body.business_status.length > 0 && {
        business_status: { in: body.business_status },
      }),

    // Priority filtering
    ...(body.priority &&
      body.priority.length > 0 && {
        priority: { in: body.priority },
      }),

    // Category filtering
    ...(body.category && {
      category: { equals: body.category },
    }),

    // Text search in title and description
    ...(body.search && {
      OR: [
        { title: { contains: body.search, mode: "insensitive" } },
        { description: { contains: body.search, mode: "insensitive" } },
      ],
    }),

    // Date range filtering for creation
    ...((body.date_from || body.date_to) && {
      created_at: {
        ...(body.date_from && { gte: new Date(body.date_from) }),
        ...(body.date_to && { lte: new Date(body.date_to) }),
      },
    }),

    // Due date range filtering
    ...((body.due_date_from || body.due_date_to) && {
      due_date: {
        ...(body.due_date_from && { gte: new Date(body.due_date_from) }),
        ...(body.due_date_to && { lte: new Date(body.due_date_to) }),
      },
    }),

    // Include/exclude completed todos
    ...(body.include_completed === false && {
      status: { not: "completed" },
    }),
  };

  // Build orderBy conditions
  const sortBy = body.sort_by ?? "created_at";
  const sortOrder = body.sort_order ?? "asc";

  const orderBy: Record<string, "asc" | "desc"> = {};
  orderBy[sortBy] = sortOrder;

  // Execute query with pagination
  const [todos, total] = await Promise.all([
    MyGlobal.prisma.todo_app_todos.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.todo_app_todos.count({
      where: whereConditions,
    }),
  ]);

  // Transform results to match API interface
  const data = todos.map((todo) => ({
    id: todo.id,
    title: todo.title,
    description: todo.description ?? undefined,
    status: typia.assert<"pending" | "in_progress" | "completed" | "cancelled">(
      todo.status,
    ),
    business_status: typia.assert<"active" | "on_hold" | "archived">(
      todo.business_status,
    ),
    priority: typia.assert<"low" | "medium" | "high" | "urgent">(todo.priority),
    category: todo.category ?? undefined,
    due_date: todo.due_date ? toISOStringSafe(todo.due_date) : undefined,
    created_at: toISOStringSafe(todo.created_at),
    updated_at: toISOStringSafe(todo.updated_at),
    completed_at: todo.completed_at
      ? toISOStringSafe(todo.completed_at)
      : undefined,
  }));

  // Calculate pagination metadata
  const totalPages = Math.ceil(total / limit);

  return {
    data,
    pagination: {
      current: page,
      limit,
      records: total,
      pages: totalPages,
    },
  };
}

