import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function putTodoAppMemberMembersMemberId(props: {
  member: MemberPayload;
  memberId: string & tags.Format<"uuid">;
  body: ITodoAppMember.IUpdate;
}): Promise<ITodoAppMember> {
  // Verify member can only update their own profile
  if (props.member.id !== props.memberId) {
    throw new HttpException("Cannot update another member profile", 403);
  }

  // Check if member exists and is active
  const existingMember = await MyGlobal.prisma.todo_app_members.findUnique({
    where: { id: props.memberId },
  });

  if (!existingMember) {
    throw new HttpException("Member not found", 404);
  }

  if (existingMember.deleted_at !== null) {
    throw new HttpException("Cannot update deleted member account", 400);
  }

  if (existingMember.status !== "active") {
    throw new HttpException("Cannot update inactive member account", 400);
  }

  // Build update data with only provided fields using object spread
  const updateData: any = {
    updated_at: toISOStringSafe(new Date()),
  };

  if (props.body.first_name !== undefined) {
    updateData.first_name = props.body.first_name;
  }

  if (props.body.last_name !== undefined) {
    updateData.last_name = props.body.last_name;
  }

  if (props.body.status !== undefined) {
    updateData.status = props.body.status;
  }

  // Update member profile
  const updated = await MyGlobal.prisma.todo_app_members.update({
    where: { id: props.memberId },
    data: updateData,
  });

  return {
    id: updated.id,
    email: updated.email,
    first_name: updated.first_name ?? undefined,
    last_name: updated.last_name ?? undefined,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at
      ? toISOStringSafe(updated.deleted_at)
      : undefined,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { MemberPayload } from "../decorators/payload/MemberPayload";

export async function patchTodoAppMemberTodos(props: {
  member: MemberPayload;
  body: ITodoAppTodo.IRequest;
}): Promise<IPageITodoAppTodo.ISummary> {
  // Extract pagination parameters with defaults
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;

  // Build the where condition for filtering
  const whereConditions: any = {
    todo_app_member_id: props.member.id,
    deleted_at: null, // Only show non-deleted items
  };

  // Add text search filter
  if (props.body.search) {
    whereConditions.OR = [
      { title: { contains: props.body.search } },
      { description: { contains: props.body.search } },
    ];
  }

  // Add status filtering
  if (props.body.status && props.body.status.length > 0) {
    whereConditions.status = { in: props.body.status };
  }

  // Add priority filtering
  if (props.body.priority && props.body.priority.length > 0) {
    whereConditions.priority = { in: props.body.priority };
  }

  // Add category filtering
  if (props.body.category) {
    whereConditions.category = props.body.category;
  }

  // Add business status filtering
  if (props.body.business_status && props.body.business_status.length > 0) {
    whereConditions.business_status = { in: props.body.business_status };
  }

  // Add date range filtering for creation dates
  if (props.body.date_from || props.body.date_to) {
    whereConditions.created_at = {};
    if (props.body.date_from)
      whereConditions.created_at.gte = props.body.date_from;
    if (props.body.date_to) whereConditions.created_at.lte = props.body.date_to;
  }

  // Add due date range filtering
  if (props.body.due_date_from || props.body.due_date_to) {
    whereConditions.due_date = {};
    if (props.body.due_date_from)
      whereConditions.due_date.gte = props.body.due_date_from;
    if (props.body.due_date_to)
      whereConditions.due_date.lte = props.body.due_date_to;
  }

  // Handle completed todo filtering
  if (props.body.include_completed === false) {
    whereConditions.status = { not: "completed" };
  }

  // Build sorting configuration
  const sortBy = props.body.sort_by ?? "created_at";
  const sortOrder = props.body.sort_order ?? "desc";

  let orderBy: any;
  if (sortBy === "priority") {
    // Priority sorting with custom order mapping
    const priorityOrder = { urgent: 4, high: 3, medium: 2, low: 1 };
    orderBy = { priority: { sort: sortOrder, nulls: "last" } };
  } else if (sortBy === "title" || sortBy === "status") {
    orderBy = { [sortBy]: sortOrder };
  } else {
    // For date fields, handle potential null values
    orderBy = { [sortBy]: { sort: sortOrder, nulls: "last" } };
  }

  // Execute database queries in parallel for efficiency
  const [data, total] = await Promise.all([
    MyGlobal.prisma.todo_app_todos.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy,
      select: {
        id: true,
        title: true,
        description: true,
        status: true,
        business_status: true,
        priority: true,
        category: true,
        due_date: true,
        completed_at: true,
        created_at: true,
        updated_at: true,
      },
    }),
    MyGlobal.prisma.todo_app_todos.count({
      where: whereConditions,
    }),
  ]);

  // Transform database results to API format
  const transformedData = data.map((todo) => ({
    id: todo.id,
    title: todo.title,
    description: todo.description ?? undefined,
    status: typia.assert<"pending" | "in_progress" | "completed" | "cancelled">(
      todo.status,
    ),
    business_status: typia.assert<"active" | "on_hold" | "archived">(
      todo.business_status,
    ),
    priority: typia.assert<"low" | "medium" | "high" | "urgent">(todo.priority),
    category: todo.category ?? undefined,
    due_date: todo.due_date ? toISOStringSafe(todo.due_date) : undefined,
    created_at: toISOStringSafe(todo.created_at),
    updated_at: toISOStringSafe(todo.updated_at),
    completed_at: todo.completed_at
      ? toISOStringSafe(todo.completed_at)
      : undefined,
  }));

  // Calculate pagination metadata
  const pages = Math.ceil(total / limit);
  const pagination = {
    current: page,
    limit,
    records: total,
    pages,
  };

  return {
    data: transformedData,
    pagination,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdministrator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postAuthAdminLogin(props: {
  admin: AdminPayload;
  body: ITodoAppAdministrator.ILogin;
}): Promise<ITodoAppAdministrator.IAuthorized> {
  // Phase 1: Validate administrator credentials
  const admin = await MyGlobal.prisma.todo_app_administrators.findFirst({
    where: { email: props.body.email },
  });

  if (!admin) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Check if account is active and not deleted
  if (admin.status !== "active" || admin.deleted_at !== null) {
    throw new HttpException("Account is inactive or deactivated", 403);
  }

  // Verify password using PasswordUtil
  const isValidPassword = await PasswordUtil.verify(
    props.body.password,
    admin.password_hash,
  );

  if (!isValidPassword) {
    throw new HttpException("Invalid credentials", 401);
  }

  // Phase 2: Create new session record
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const session = await MyGlobal.prisma.todo_app_administrator_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      administrator_id: admin.id,
      ip: props.body.ip,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: new Date().toISOString(),
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  // Phase 3: Generate JWT tokens
  const currentTimestamp = new Date().toISOString();

  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: currentTimestamp,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: currentTimestamp,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Return authenticated administrator information
  return {
    id: admin.id,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdministrator";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postAuthAdminRefresh(props: {
  admin: AdminPayload;
  body: ITodoAppAdministrator.IRefresh;
}): Promise<ITodoAppAdministrator.IAuthorized> {
  // Verify and decode the refresh token
  let decoded: {
    id: string;
    session_id: string;
    type: "admin";
  };
  try {
    decoded = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      { issuer: "autobe" },
    ) as {
      id: string;
      session_id: string;
      type: "admin";
    };
  } catch (error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Validate the token type matches admin
  if (decoded.type !== "admin") {
    throw new HttpException("Invalid token type", 403);
  }

  // Validate session exists and belongs to the admin
  const session =
    await MyGlobal.prisma.todo_app_administrator_sessions.findFirst({
      where: {
        id: decoded.session_id,
        administrator_id: decoded.id,
        // Check if session is not expired (expired_at is null or in the future)
        OR: [{ expired_at: null }, { expired_at: { gt: new Date() } }],
      },
      include: {
        administrator: true,
      },
    });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  } else if (session.administrator.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  // Generate new tokens with SAME session_id to maintain session continuity
  const accessExpires: Date = new Date(Date.now() + 60 * 60 * 1000); // 1 hour
  const refreshExpires: Date = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id, // SAME session_id for continuity
        created_at: new Date().toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id, // SAME session_id for continuity
        tokenType: "refresh",
        created_at: new Date().toISOString(),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Update session expiration time
  await MyGlobal.prisma.todo_app_administrator_sessions.update({
    where: {
      id: decoded.session_id,
    },
    data: {
      expired_at: refreshExpires,
    },
  });

  // Return the new tokens and admin info
  return {
    id: session.administrator.id,
    token: token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IPageIAuthSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAuthSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IAuthSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthSession";
import { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getTodoAppAdminAuthSessions(props: {
  admin: AdminPayload;
}): Promise<IPageIAuthSession> {
  const page = 1;
  const limit = 100;
  const skip = (page - 1) * limit;

  // Query member sessions with user data
  const memberSessions =
    await MyGlobal.prisma.todo_app_member_sessions.findMany({
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
      include: {
        member: {
          select: {
            id: true,
            email: true,
            first_name: true,
            last_name: true,
            status: true,
          },
        },
      },
    });

  // Query administrator sessions with user data
  const adminSessions =
    await MyGlobal.prisma.todo_app_administrator_sessions.findMany({
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
      include: {
        administrator: {
          select: {
            id: true,
            email: true,
            first_name: true,
            last_name: true,
            status: true,
          },
        },
      },
    });

  // Transform member sessions to unified format
  const memberAuthSessions: IAuthSession[] = memberSessions.map((session) => ({
    id: session.id as string & tags.Format<"uuid">,
    user: {
      id: session.member.id as string & tags.Format<"uuid">,
      email: session.member.email,
      first_name: session.member.first_name ?? undefined,
      last_name: session.member.last_name ?? undefined,
      status: session.member.status,
    },
    user_type: "member" as const,
    ip: session.ip,
    href: session.href as string & tags.Format<"uri">,
    referrer: session.referrer as string & tags.Format<"uri">,
    created_at: toISOStringSafe(session.created_at),
  }));

  // Transform administrator sessions to unified format
  const adminAuthSessions: IAuthSession[] = adminSessions.map((session) => ({
    id: session.id as string & tags.Format<"uuid">,
    user: {
      id: session.administrator.id as string & tags.Format<"uuid">,
      email: session.administrator.email,
      first_name: session.administrator.first_name ?? undefined,
      last_name: session.administrator.last_name ?? undefined,
      status: session.administrator.status,
    },
    user_type: "administrator" as const,
    ip: session.ip,
    href: session.href as string & tags.Format<"uri">,
    referrer: session.referrer as string & tags.Format<"uri">,
    created_at: toISOStringSafe(session.created_at),
  }));

  // Combine and sort by creation date
  const allSessions = [...memberAuthSessions, ...adminAuthSessions].sort(
    (a, b) =>
      new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
  );

  // Get total count from both tables
  const [memberTotal, adminTotal] = await Promise.all([
    MyGlobal.prisma.todo_app_member_sessions.count(),
    MyGlobal.prisma.todo_app_administrator_sessions.count(),
  ]);

  const total = memberTotal + adminTotal;

  return {
    data: allSessions.slice(0, limit),
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

