import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdministrator";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getTodoAppAdministratorsAdministratorId(props: {
  admin: AdminPayload;
  administratorId: string & tags.Format<"uuid">;
}): Promise<ITodoAppAdministrator.ISummary> {
  // Verify admin authorization is valid
  if (props.admin.type !== "admin") {
    throw new HttpException("Unauthorized", 403);
  }

  // Find administrator by ID, excluding soft deleted records
  const administrator = await MyGlobal.prisma.todo_app_administrators.findFirst(
    {
      where: {
        id: props.administratorId,
        deleted_at: null, // Exclude soft deleted records
      },
      select: {
        id: true,
        email: true,
        first_name: true,
        last_name: true,
        role_level: true,
        created_at: true,
      },
    },
  );

  if (!administrator) {
    throw new HttpException("Administrator not found", 404);
  }

  // Return administrator summary excluding sensitive fields
  return {
    id: administrator.id,
    email: administrator.email,
    first_name: administrator.first_name ?? "",
    last_name: administrator.last_name ?? "",
    role_level: administrator.role_level,
    created_at: toISOStringSafe(administrator.created_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteTodoAppAdminAdministratorsAdministratorId(props: {
  admin: AdminPayload;
  administratorId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Verify target administrator exists and is active
  const targetAdministrator =
    await MyGlobal.prisma.todo_app_administrators.findFirst({
      where: {
        id: props.administratorId,
        deleted_at: null,
      },
    });

  if (!targetAdministrator) {
    throw new HttpException("Administrator not found or already deleted", 404);
  }

  // Prevent self-deletion for security
  if (targetAdministrator.id === props.admin.id) {
    throw new HttpException(
      "Cannot delete your own administrator account",
      403,
    );
  }

  // Perform soft delete by setting deleted_at timestamp
  await MyGlobal.prisma.todo_app_administrators.update({
    where: { id: props.administratorId },
    data: {
      deleted_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
    },
  });
}

