  public async erase(
    @AdminAuth()
    admin: AdminPayload,
    @TypedParam("configKey")
    configKey: string,
  ): Promise<ITodoAppSystemMetadata> {
    try {
      return await deleteTodoAppAdminSystemMetadataConfigKey({
        admin,
        configKey,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}
